def transform(grid):
    out = [row[:] for row in grid]
    gates = []
    for r, row in enumerate(grid):
        greens = [c for c, v in enumerate(row) if v == 3]
        if greens:
            gates.append((r, greens[len(greens) // 2]))
    barrier_rows = {r for r, _ in gates}
    markers = []
    for r, row in enumerate(grid):
        for c, v in enumerate(row):
            if v != 4 and v != 3 and r not in barrier_rows:
                markers.append((r, c, v))
    markers.sort()
    color = markers[0][2]
    r, c = markers[0][0], markers[0][1]
    for gr, gc in gates:
        for rr in range(r, gr):
            out[rr][c] = color
        out[gr - 1][c] = color
        for cc in range(min(c, gc), max(c, gc) + 1):
            out[gr - 1][cc] = color
        out[gr][gc] = color
        r, c = gr + 1, gc
    end_r, end_c, _ = markers[-1]
    for rr in range(r, end_r + 1):
        out[rr][c] = color
    for cc in range(min(c, end_c), max(c, end_c) + 1):
        out[end_r][cc] = color
    return out
